command:
/* Rajada — Tiago's Toolkit: Sons */
const CAMINHOS = ["psfx.ranged-weapons.guns.single-fire.revolver.0", "psfx.ranged-weapons.guns.single-fire.revolver.2", "psfx.ranged-weapons.guns.single-fire.revolver.4"];

if (!game.modules.get("sequencer")?.active)
  return ui.notifications.warn("Este som precisa do módulo Sequencer ativo.");
if (!game.modules.get("psfx")?.active)
  return ui.notifications.warn("Este som precisa do módulo PSFX ativo.");
if (!CAMINHOS.every(c => Sequencer.Database.entryExists(c)))
  return ui.notifications.warn("Este som não foi encontrado no PSFX. Atualize o módulo PSFX.");

const seq = new Sequence();
seq.sound().file("psfx.ranged-weapons.guns.single-fire.revolver.0").volume(1);
seq.sound().file("psfx.ranged-weapons.guns.single-fire.revolver.2").volume(0.95).delay(170);
seq.sound().file("psfx.ranged-weapons.guns.single-fire.revolver.4").volume(0.9).delay(340);
seq.play();
